    'admin_shadow-saas-grip.abort_failed_prefix' => '中止同步失败：',
    'admin_shadow-saas-grip.abort_grip_confirm' => '中止正在运行的 Grip 同步？',
    'admin_shadow-saas-grip.abort_hero_confirm' => '中止正在运行的 HERO 同步？',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security 会在您的整个环境中发现并持续监控作为记录来源的 SaaS 应用。
本集成：<br><br>
<strong>&bull; 镜像 Grip 数据：</strong> 将完整的 SaaS / 用户 / 告警清单拉取到 <code>shadow_saas_grip_*</code> 表中。<br>
<strong>&bull; 填充 Shadow SaaS：</strong> 将每个 SaaS 应用投影到现有的 Shadow SaaS 列表中，将 URL 规范化为其可注册域名，使供应商匹配与 CSV 导入的方式相同。<br>
<strong>&bull; 跟踪风险：</strong> 保留 Grip 的风险评分、批准标签、OAuth 范围计数、AI 深度分类、MFA / SAML 支持情况以及主要联系人元数据。<br>
<strong>&bull; 保持最新：</strong> 按配置的 cron 计划重新运行；管理员也可通过上方的 “立即运行” 按钮触发一次立即的后台运行。',
    'admin_shadow-saas-grip.about_grip_heading' => '关于 Grip 集成',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security 会在您的整个环境中发现第三方 SaaS 供应商及其面临的问题。
本集成：<br><br>
<strong>&bull; 镜像 HERO 数据：</strong> 将供应商 / 问题 / 每个供应商的用户拉取到 <code>shadow_saas_hero_*</code> 表中。<br>
<strong>&bull; 填充 Shadow SaaS：</strong> 按可注册域名将每个供应商投影到现有的 Shadow SaaS 列表中，使匹配与 CSV 导入的方式相同。<br>
<strong>&bull; 跟踪风险：</strong> 从每个供应商最严重的未解决问题派生出 1-5 的风险评分（与 Grip 使用的 1-5 量表相同），并记录供应商的状态和参与方面。<br>
<strong>&bull; 保持最新：</strong> 在共享的计划重新填充作业中重新运行；管理员也可通过下方的 “立即运行” 按钮触发一次立即运行。',
    'admin_shadow-saas-grip.about_hero_heading' => '关于 HERO 集成',
    'admin_shadow-saas-grip.api_key_label' => 'API 密钥',
    'admin_shadow-saas-grip.api_reference_heading' => 'API 参考',
    'admin_shadow-saas-grip.api_token_help' => '在每次请求时作为 <code>access-token</code> HTTP 标头发送。留空以保留现有令牌。',
    'admin_shadow-saas-grip.api_token_label' => 'API 令牌',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => '不允许使用该 API URL 主机。',
    'admin_shadow-saas-grip.api_url_invalid' => 'API URL 必须是有效的 http(s) URL。',
    'admin_shadow-saas-grip.api_url_label' => 'API URL',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' 个含用户的应用',
    'admin_shadow-saas-grip.client_id_label' => '客户端 ID',
    'admin_shadow-saas-grip.client_secret_label' => '客户端密钥',
    'admin_shadow-saas-grip.currently_holding_prefix' => '当前保存 ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>实时</strong> 会在每个页面调用 Grip API（始终为最新，对 API 负担较重）。<strong>本地（已填充/已缓存）</strong> 提供数据库中已填充的 <code>shadow_saas_grip_*</code> 表 - 对 API 负担较轻 - 缺失的单个应用快照会从 API 获取一次，然后缓存。在本地模式下，每次同步会 <strong>完全刷新</strong> 数据：Grip 镜像表会被清空并从 API 重新填充。',
