    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Grip Security 公共 API 的端点清单（服务器基础 <code>https://&lt;tenant&gt;.dep.grip.security/public</code>，自动生成的 OpenAPI 3.1）。FairTPRM 同步使用标记为 <em>同步所用</em> 的读取（GET）端点；完整清单 &mdash; 包括 Users、Workflows、Posture&nbsp;Management、AuditLogs、Alerts / Alerts&nbsp;V2、Actions 和 AI&nbsp;Agents 分组 &mdash; 位于下方的 OpenAPI 和 Postman 下载中。域名提取会将 URL 规范化为其可注册域名（例如 <code>https://www.united.com</code> → <code>united.com</code>，<code>http://color.redhat.com</code> → <code>redhat.com</code>）。',
    'admin_shadow-saas-grip.grip_auth_help' => '身份验证标头：<code>access-token: &lt;your-token&gt;</code>。Postman 集合的 <code>accessToken</code> 变量设置为 <code>REPLACE_ME</code>；在发送请求前请替换为您的租户令牌。',
    'admin_shadow-saas-grip.grip_base_url_help' => '以 <code>/public/saas</code> 为根的租户前缀 Grip URL（例如 <code>https://tenant.dep.grip.security/public/saas</code>）。同级端点（<code>/public/users</code>、<code>/public/alerts</code>）由此主机推导得出。',
    'admin_shadow-saas-grip.grip_base_url_label' => '服务器（租户基础 URL）',
    'admin_shadow-saas-grip.grip_breach_help' => '在每次计划重新填充（以及下方的手动 <strong>立即运行</strong>）时，Grip “检测到安全事件” 告警会被写入 <a href="breach-alerts.php">泄露&nbsp;/&nbsp;网络告警</a> 系统（并去重）。已入驻供应商的泄露事件会关联到该供应商；没有已入驻供应商的应用的泄露事件仍会被记录，并标记为 <strong>Shadow&nbsp;SaaS</strong>，附带可能受影响的用户数量。需要启用 Grip（上方）<em>并且</em>启用 <a href="admin.php?section=email">电子邮件与告警</a> 下的泄露&nbsp;/&nbsp;网络告警设置。',
